import React from 'react';
import {usePersistentState} from './shared';
import sourceManifest from '../sourceManifest.json' with {type:'json'};
import {sourceLocation,resolveSourceReference} from '../collectionModel.mjs';
export function EvidenceSearch({onInspect,index,sources=[]}){const [query,setQuery]=usePersistentState('curricupath-evidence-finder-v1','');const activeSources=Object.fromEntries(sources.map(s=>[s.source_id,resolveSourceReference(s,sourceManifest[s.source_id])]));const all=[...(index?.records || []),...Object.values(activeSources).map(s=>({...s,kind:'source'}))];const matches=query.trim()?all.filter(r=>[r.kind,r.id,r.title,r.source_id].join(' ').toLowerCase().includes(query.trim().toLowerCase())).slice(0,30):[];return <section className="evidence-search"><span className="eyebrow">Find the exact reference</span><h2>Follow the evidence.</h2><label className="workspace-field">Find a module, rule or source title<input name="evidence-finder" autoComplete="off" spellCheck={false} value={query} onChange={e=>setQuery(e.target.value)} placeholder="For example, ELEN4025, PRE_ELEN4025 or Senate…"/></label><p className="helper-text">Searches the current server catalogue. No private declarations are part of this search. Archived document links require a compatible recorded edition and verification.</p>{!index && <p className="workspace-warning">Module and rule search coverage is unavailable. Source titles remain searchable.</p>}{index?.fingerprint && <details><summary>Evidence search snapshot</summary><p className="helper-text">Public index reference: <code>{index.fingerprint.slice(0,16)}</code>. This identifies these search records, not every eligibility input. Reopen the register to refresh current records.</p></details>}<p role="status">{query.trim()?`${matches.length} results shown (maximum 30)`:'Enter an identifier or title to find the recorded source.'}</p>{matches.map((r,i)=>{const source={...(activeSources[r.source_id || r.id] || {}),page:r.page};const link=sourceLocation(source);return <article key={`${r.kind}-${r.id}-${i}`}><span className="eyebrow">{r.kind}</span><strong>{r.id} · {r.title}</strong><small>{r.source_id || r.id}{r.page?` · printed page ${r.page}`:''}</small><div className="workspace-toolbar">{(r.kind==='module' || r.module) && <button className="secondary-button" onClick={()=>onInspect(r.module || r.id)}>Inspect recorded module</button>}{link?<a className="text-button" href={link} target="_blank" rel="noreferrer">Open exact source location</a>:<span>Accessible verified link not available; retain the identifier for review.</span>}</div></article>;})}{query.trim() && !matches.length && <button className="text-button" onClick={()=>setQuery('')}>Clear evidence search</button>}</section>;}
export default EvidenceSearch;
