import React,{useState} from 'react';
import {AsyncPanel} from './shared';
export function ExplorePage({modules=[],profile,onOpenModule,onAsk,onProfile,loading,error,onRetry}){
 const [query,setQuery]=useState(''),[year,setYear]=useState('3'),[electives,setElectives]=useState(false);
 const rows=modules.filter(m=>(!year || String(m.year_of_study)===year)&&(!electives || m.requirement_type==='elective_pool')&&`${m.course_code} ${m.course_name}`.toLowerCase().includes(query.toLowerCase()));
 const ask=`Which ${electives?'electives':'modules'} ${year?'in year '+year+' ':''}am I eligible for?`;
 return <div className="page-content explore-page"><header className="page-heading"><span className="eyebrow">Your Wits curriculum</span><h1>Find your next module.</h1><p>Browse recorded Wits modules. Check eligibility against your declared history, or ask for suggestions based on your interests.</p></header>
 {!profile.programme?<section className="empty-panel"><h2>Choose your programme first.</h2><button className="primary-button" onClick={onProfile}>Set up degree profile</button></section>:<>
 <section className="discovery-filter-panel"><label className="workspace-field">Search Wits modules<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Module code or name"/></label><label className="workspace-field">Curriculum year<select value={year} onChange={e=>setYear(e.target.value)}><option value="">All years</option>{[1,2,3,4].map(y=><option key={y} value={y}>Year {y}</option>)}</select></label><label><input type="checkbox" checked={electives} onChange={e=>setElectives(e.target.checked)}/> Electives only</label><div className="workspace-toolbar"><button className="primary-button" onClick={()=>onAsk(ask)}>List what I am eligible for</button><button className="secondary-button" onClick={()=>onAsk(`Recommend ${year?'year '+year+' ':''}${electives?'electives':'Wits modules'} for my interests`)}>Recommend for my interests</button></div><p>Catalogue membership is not proof of eligibility. The Advisor checks each module and explains missing or unmet requirements.</p></section>
 <AsyncPanel loading={loading} error={error} onRetry={onRetry} title="Wits modules"/><p role="status">{rows.length} Wits modules</p><div className="module-list">{rows.map(m=><article className="chat-result-card" key={m.course_code}><span className="module-code">{m.course_code}</span><h3>{m.course_name}</h3><p>Year {m.year_of_study} ? {m.nqf_credits} credits ? {m.requirement_type==='elective_pool'?'Elective':'Compulsory'}</p><button className="text-button" onClick={()=>onOpenModule(m.course_code)}>View requirements</button><button className="secondary-button" onClick={()=>onAsk(`Can I take ${m.course_code}?`)}>Check my eligibility</button></article>)}</div></>}
 </div>;
}
